-- ═══════════════════════════════════════════════════════════════
-- DNALABS(우리 회사) 계정의 **보여 주기용 예시 자료**
--
-- 손님께 화면을 보여 드릴 때 빈 목록을 띄우지 않으려고 넣어 둡니다.
-- 다른 회사에는 보이지 않습니다 — 데이터베이스가 회사 단위로 가릅니다.
--
-- ⚠ 연락처·사업자번호는 **우리 것**을 씁니다. 남의 번호를 예시로 박아 두면
--    그 사람에게 전화가 갑니다.
-- ⚠ 날짜는 오늘을 기준으로 셈합니다. 날짜를 박아 두면 몇 달 뒤에 다시 볼 때
--    전부 "납기 지남" 이 됩니다.
-- ⚠ id 가 d511 로 시작하는 것이 예시 자료입니다. 다시 돌려도 되고,
--    아래 delete 한 줄로 깨끗이 지울 수 있습니다.
--
--   돌리기: supabase db query --linked -f sql/0005_demo_dnalabs.sql
-- ═══════════════════════════════════════════════════════════════

delete from public.order_lines  where company_id = 'befcd957-8bc3-45a4-8cc1-652875d3f0d7' and id::text like 'd514%';
delete from public.orders       where company_id = 'befcd957-8bc3-45a4-8cc1-652875d3f0d7' and id::text like 'd513%';
delete from public.supply_items where company_id = 'befcd957-8bc3-45a4-8cc1-652875d3f0d7' and id::text like 'd512%';
delete from public.stores       where company_id = 'befcd957-8bc3-45a4-8cc1-652875d3f0d7' and id::text like 'd511%';

