select (select count(*) from public.stores       where company_id = 'befcd957-8bc3-45a4-8cc1-652875d3f0d7' and not deleted) as 점포,
       (select count(*) from public.supply_items where company_id = 'befcd957-8bc3-45a4-8cc1-652875d3f0d7' and not deleted) as 품목,
       (select count(*) from public.orders       where company_id = 'befcd957-8bc3-45a4-8cc1-652875d3f0d7' and not deleted) as 발주,
       (select count(*) from public.order_lines  where company_id = 'befcd957-8bc3-45a4-8cc1-652875d3f0d7')                 as 발주줄;
